css:
.site-header {
  position: sticky;
  z-index: 20;
  top: 0;
  border-bottom: 1px solid rgb(var(--color-line) / 0.76);
  background: rgb(var(--color-canvas) / 0.92);
  backdrop-filter: blur(14px);
}

.site-nav {
  display: flex;
  width: min(100% - 3rem, 1440px);
  height: 76px;
  align-items: center;
  justify-content: space-between;
  margin: 0 auto;
}

.nav-brand {
  color: rgb(var(--color-ink));
  font-size: 1.1rem;
  font-weight: 650;
  letter-spacing: -0.055em;
  text-decoration: none;
}

.nav-brand-period { color: rgb(var(--color-accent)); }

.nav-links, .nav-actions { display: flex; align-items: center; }
.nav-links { gap: clamp(1.1rem, 2vw, 2rem); }
.nav-actions { gap: 0.7rem; }
.theme-toggle { display: grid; width: 40px; height: 40px; flex: 0 0 auto; place-items: center; border: 1px solid rgb(var(--color-line)); border-radius: 50%; background: rgb(var(--color-surface)); color: rgb(var(--color-ink)); cursor: pointer; transition: background-color 180ms ease, border-color 180ms ease, color 180ms ease, transform 160ms ease; }
.theme-toggle:hover { transform: translateY(-1px); border-color: rgb(var(--color-accent) / 0.42); color: rgb(var(--color-accent)); }
.theme-toggle:focus-visible { outline: none; box-shadow: var(--focus-ring); }

.nav-link {
  color: rgb(var(--color-muted));
  font-size: 0.83rem;
  font-weight: 520;
  text-decoration: none;
}

.nav-link-pending { cursor: default; opacity: 0.82; }
.nav-resume { min-height: 2.55rem; padding: 0.65rem 0.9rem; font-size: 0.82rem; }
.mobile-menu-toggle, .mobile-nav { display: none; }

.hero-main { width: 100%; }
.hero {
  position: relative;
  display: grid;
  width: min(100% - 3rem, 1440px);
  min-height: min(790px, calc(100svh - 76px));
  grid-template-columns: minmax(0, 1fr) minmax(420px, 0.92fr);
  align-items: center;
  margin: 0 auto;
  padding: clamp(4rem, 7vw, 7rem) 0 clamp(5.5rem, 8vw, 8rem);
}

.hero-copy { position: relative; z-index: 2; padding: 0 0 0 clamp(0px, 3vw, 44px); }
.hero-eyebrow { display: flex; align-items: center; gap: 0.65rem; margin-bottom: 1.65rem; }
.eyebrow-mark { width: 7px; height: 7px; border-radius: 50%; background: rgb(var(--color-accent)); }
.hero-title { max-width: 10ch; font-size: clamp(4rem, 7.3vw, 7.3rem); line-height: 0.99; }
.hero-title span { color: rgb(var(--color-accent)); }
.hero-description { margin-top: 1.8rem; max-width: 38rem; color: rgb(var(--color-muted)); font-size: clamp(1rem, 1.25vw, 1.12rem); }
.hero-actions { display: flex; flex-wrap: wrap; gap: 0.7rem; margin-top: 2rem; }
.hero-scroll { display: inline-flex; align-items: center; gap: 0.5rem; margin-top: 4.4rem; color: rgb(var(--color-muted)); font-size: 0.76rem; text-decoration: none; }
.hero-scroll:hover { color: rgb(var(--color-accent)); }
.hero-eyebrow, .hero-copy > div, .hero-scroll { animation: reveal-up 700ms both; }
.hero-eyebrow { animation-delay: 40ms; }
.hero-copy > div:nth-of-type(1) { animation-delay: 130ms; }
.hero-copy > div:nth-of-type(2) { animation-delay: 220ms; }
.hero-copy > div:nth-of-type(3) { animation-delay: 310ms; }
.hero-scroll { animation-delay: 410ms; }

.hero-stage { position: relative; min-height: 550px; isolation: isolate; }
.hero-stage { animation: reveal-up 800ms 150ms both; }
.stage-orbit { position: absolute; z-index: -1; top: 50%; left: 51%; border: 1px solid rgb(var(--hero-grid) / 0.66); border-radius: 50%; transform: translate(-50%, -50%); }
.stage-orbit-one { width: min(88%, 470px); aspect-ratio: 1; }
.stage-orbit-two { width: min(67%, 360px); aspect-ratio: 1; border-style: dashed; opacity: 0.58; }
.float-card { position: absolute; display: flex; flex-direction: column; }
.float-label { color: rgb(var(--color-muted)); font-size: 0.63rem; font-weight: 650; letter-spacing: 0.1em; text-transform: uppercase; }
.identity-card { top: 8%; left: 10%; width: 300px; min-height: 102px; flex-direction: row; align-items: center; gap: 0.85rem; padding: 1rem; animation: drift-a 7s ease-in-out infinite; }
.identity-symbol { display: flex; width: 46px; height: 46px; flex: 0 0 auto; align-items: center; justify-content: center; border-radius: 15px; background: rgb(var(--color-accent)); color: rgb(var(--accent-foreground)); font-size: 1.35rem; font-weight: 550; letter-spacing: -0.08em; }
.identity-symbol span { color: rgb(var(--accent-highlight)); }
.float-card-copy { display: flex; min-width: 0; flex-direction: column; gap: 0.18rem; }
.float-card-copy strong { overflow: hidden; color: rgb(var(--color-ink)); font-size: 0.81rem; font-weight: 620; text-overflow: ellipsis; white-space: nowrap; }
.float-card-copy > span:last-child { color: rgb(var(--color-muted)); font-size: 0.68rem; }
.identity-presence { width: 7px; height: 7px; flex: 0 0 auto; align-self: flex-start; margin: 0.28rem 0 0 auto; border-radius: 50%; background: rgb(var(--status-good)); box-shadow: 0 0 0 3px rgb(var(--status-good) / 0.12); }
.build-card { top: 32%; right: 0; width: 250px; min-height: 184px; padding: 1.05rem 1.1rem; animation: drift-b 8s ease-in-out infinite; }
.card-topline { display: flex; align-items: center; justify-content: space-between; gap: 0.4rem; }
.build-status { display: inline-flex; align-items: center; gap: 0.3rem; color: rgb(var(--color-muted)); font-size: 0.61rem; white-space: nowrap; }
.build-status span { width: 5px; height: 5px; border-radius: 50%; background: rgb(var(--status-idle)); }
.build-project-icon { display: grid; width: 35px; height: 35px; place-items: center; margin: 1.1rem 0 0.55rem; border-radius: 11px; background: rgb(var(--color-accent-soft)); color: rgb(var(--color-accent)); }
.build-card > strong { color: rgb(var(--color-ink)); font-size: 0.93rem; font-weight: 620; letter-spacing: -0.025em; }
.build-card > span:last-child { margin-top: 0.2rem; color: rgb(var(--color-muted)); font-size: 0.72rem; }
.stack-card { top: 67%; left: 4%; width: 260px; gap: 0.75rem; padding: 1rem 1.05rem; animation: drift-c 7.5s ease-in-out infinite; }
.stack-tags { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.stack-tags .ds-tag { min-height: 1.55rem; padding: 0.3rem 0.55rem; font-size: 0.64rem; }
.terminal-card { top: 45%; left: 0; width: 196px; gap: 0.32rem; padding: 0.8rem 0.9rem 0.9rem; background: rgb(var(--surface-elevated) / 0.98); animation: drift-a 8.5s ease-in-out infinite; }
.terminal-top { display: flex; align-items: center; gap: 4px; margin-bottom: 0.4rem; }
.terminal-top > span { width: 5px; height: 5px; border-radius: 50%; background: rgb(var(--color-line-strong)); }
.terminal-top small { margin-left: auto; color: rgb(var(--color-muted)); font-size: 0.56rem; }
.terminal-card code { color: rgb(var(--color-ink)); font-size: 0.68rem; }
.terminal-card code i { color: rgb(var(--color-accent)); font-style: normal; }
.terminal-card strong { margin-top: 0.2rem; color: rgb(var(--color-ink)); font-size: 0.75rem; font-weight: 580; }
.terminal-card > span { color: rgb(var(--color-muted)); font-size: 0.65rem; }
.social-card { top: 9%; right: 2%; width: 165px; gap: 0.8rem; padding: 0.9rem; animation: drift-b 8s ease-in-out infinite; }
.social-icons { display: flex; gap: 0.45rem; }
.social-icons a { display: grid; width: 32px; height: 32px; place-items: center; border: 1px solid rgb(var(--color-line)); border-radius: 50%; color: rgb(var(--color-ink)); transition: color 150ms ease, background 150ms ease, border-color 150ms ease; }
.social-icons a:hover { border-color: rgb(var(--color-accent) / 0.2); background: rgb(var(--color-accent-soft)); color: rgb(var(--color-accent)); }
.hero-index { position: absolute; right: 0; bottom: 2rem; display: flex; align-items: center; gap: 0.6rem; color: rgb(var(--color-muted)); font-size: 0.62rem; letter-spacing: 0.09em; }
.hero-index-line { width: 34px; height: 1px; background: rgb(var(--color-line-strong)); }
.site-footer { display: flex; width: min(100% - 3rem, 1440px); align-items: center; justify-content: space-between; margin: 0 auto; border-top: 1px solid rgb(var(--color-line)); padding: 1.1rem 0 1.4rem; color: rgb(var(--color-muted)); font-size: 0.7rem; }

@keyframes drift-a { 0%, 100% { translate: 0 0; } 50% { translate: 0 -6px; } }
@keyframes drift-b { 0%, 100% { translate: 0 0; } 50% { translate: 0 5px; } }
@keyframes drift-c { 0%, 100% { translate: 0 0; } 50% { translate: 0 -4px; } }
@keyframes reveal-up { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 1100px) {
  .hero { grid-template-columns: minmax(0, 1fr) minmax(350px, 0.8fr); }
  .hero-title { font-size: clamp(4rem, 7.8vw, 6.3rem); }
  .hero-stage { min-height: 500px; transform: scale(0.92); transform-origin: center right; }
  .social-card { display: none; }
  .identity-card { left: 1%; }
  .build-card { right: -2%; }
  .stack-card { left: 0; }
  .stack-card, .terminal-card { display: none; }
}

@media (max-width: 760px) {
  .site-nav { width: min(100% - 2rem, 1440px); height: 64px; }
  .nav-links, .nav-resume { display: none; }
  .mobile-menu-toggle { display: grid; width: 40px; height: 40px; place-items: center; border: 1px solid rgb(var(--color-line)); border-radius: 50%; background: rgb(var(--color-surface)); color: rgb(var(--color-ink)); }
  .mobile-nav { position: absolute; top: calc(100% + 0.45rem); right: 1rem; left: 1rem; display: grid; gap: 0.15rem; border: 1px solid rgb(var(--color-line)); border-radius: 1.15rem; padding: 0.65rem; background: rgb(var(--color-surface-raised)); box-shadow: var(--shadow-float); }
  .mobile-nav-link { padding: 0.7rem 0.65rem; color: rgb(var(--color-muted)); font-size: 0.9rem; }
  .mobile-nav .ds-button { margin-top: 0.35rem; }
  .hero { display: flex; min-height: unset; flex-direction: column; align-items: stretch; width: min(100% - 2rem, 600px); padding: clamp(4rem, 12vw, 6rem) 0 3rem; }
  .hero-copy { width: 100%; min-width: 0; padding: 0; }
  .hero-eyebrow { margin-bottom: 1.35rem; font-size: 0.67rem; }
  .hero-title { max-width: 10ch; font-size: clamp(3.55rem, 12.7vw, 5.7rem); }
  .hero-description { width: 100%; max-width: 100%; min-width: 0; margin-top: 1.25rem; font-size: 1rem; line-height: 1.65; }
  .hero-actions { gap: 0.55rem; margin-top: 1.55rem; }
  .hero-actions .ds-button { min-height: 2.75rem; padding: 0.7rem 0.9rem; font-size: 0.82rem; }
  .hero-scroll { margin-top: 1.5rem; }
  .hero-stage { width: 100%; max-width: 100%; min-width: 0; min-height: 280px; overflow: clip; margin-top: 1.2rem; transform: none; }
  .stage-orbit-one { width: 68%; }
  .stage-orbit-two { width: 48%; }
  .identity-card { top: 8%; left: 0; width: min(260px, 70%); min-height: 82px; padding: 0.75rem; }
  .identity-symbol { width: 38px; height: 38px; border-radius: 12px; font-size: 1.1rem; }
  .float-card-copy strong { max-width: 145px; font-size: 0.72rem; }
  .float-card-copy > span:last-child { font-size: 0.61rem; }
  .float-label { font-size: 0.56rem; }
  .build-card { top: 43%; right: 0; width: min(220px, 61%); min-height: 154px; padding: 0.8rem; }
  .build-card > strong { font-size: 0.82rem; }
  .build-card > span:last-child { font-size: 0.65rem; }
  .build-status { font-size: 0.54rem; }
  .build-project-icon { width: 30px; height: 30px; margin-top: 0.8rem; }
  .stack-card, .social-card, .terminal-card { display: none; }
  .terminal-card code { font-size: 0.6rem; }
  .terminal-card strong { font-size: 0.67rem; }
  .terminal-card > span { font-size: 0.58rem; }
  .hero-index { right: 0; bottom: 0.7rem; }
  .site-footer { width: min(100% - 2rem, 600px); gap: 0.75rem; font-size: 0.62rem; }
}

@media (max-width: 390px) {
  .hero-title { font-size: clamp(3.25rem, 13vw, 3.7rem); }
  .hero-actions { align-items: stretch; }
  .hero-actions .ds-button { flex: 1; gap: 0.35rem; padding-inline: 0.65rem; }
  .hero-stage { min-height: 250px; }
  .build-card { width: 59%; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .identity-card, .build-card, .stack-card, .terminal-card, .social-card { animation: none; }
  .social-icons a { transition: none; }
}

.about-journey-education {
  padding-bottom: clamp(5rem, 10vw, 9rem);
}

.editorial-section {
  width: min(100% - 3rem, 1320px);
  margin: 0 auto;
  border-top: 1px solid rgb(var(--color-line));
}

.about-section {
  display: grid;
  grid-template-columns: minmax(150px, 0.55fr) minmax(0, 1.45fr);
  gap: clamp(2rem, 6vw, 6rem);
  padding-top: clamp(5rem, 10vw, 9rem);
  padding-bottom: clamp(5rem, 8vw, 7rem);
}

.section-index { display: flex; flex-direction: column; align-items: flex-start; gap: 0.8rem; padding-top: 0.7rem; }
.section-index > span { display: inline-flex; align-items: center; gap: 0.5rem; color: rgb(var(--color-muted)); font-size: 0.69rem; letter-spacing: 0.06em; }
.section-index i { width: 21px; height: 1px; background: rgb(var(--color-line-strong)); }
.about-copy { max-width: 860px; }
.about-heading { max-width: 13ch; font-size: clamp(3rem, 6vw, 6.25rem); letter-spacing: -0.07em; line-height: 0.99; }
.about-introduction { max-width: 56ch; margin-top: clamp(1.5rem, 3vw, 2.5rem); color: rgb(var(--color-muted)); font-size: clamp(1.05rem, 1.5vw, 1.22rem); line-height: 1.75; }

.journey-section { padding-top: clamp(3.5rem, 6vw, 5rem); padding-bottom: clamp(5rem, 8vw, 7rem); }
.journey-heading { margin-bottom: 2.2rem; }
.journey-grid { position: relative; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: clamp(0.85rem, 2vw, 1.5rem); margin: 0; padding: 1.8rem 0 0; list-style: none; }
.journey-grid::before { position: absolute; top: 6px; right: 16.66%; left: 16.66%; height: 1px; background: rgb(var(--color-line-strong)); content: ""; }
.journey-item { position: relative; min-width: 0; padding-top: 1.15rem; }
.journey-node { position: absolute; z-index: 1; top: 0; left: 50%; width: 13px; height: 13px; border: 3px solid rgb(var(--color-canvas)); border-radius: 50%; background: rgb(var(--color-accent)); box-shadow: 0 0 0 1px rgb(var(--color-line-strong)); transform: translateX(-50%); }
.journey-card { min-height: 245px; padding: clamp(1.2rem, 2vw, 1.65rem); }
.journey-item-now .journey-card { border-color: rgb(var(--color-accent) / 0.2); box-shadow: var(--shadow-float); }
.journey-card-top { display: flex; align-items: center; justify-content: space-between; }
.journey-index { display: inline-flex; align-items: center; gap: 0.45rem; color: rgb(var(--color-muted)); font-size: 0.67rem; letter-spacing: 0.08em; }
.journey-index i { width: 16px; height: 1px; background: rgb(var(--color-line-strong)); }
.journey-card h3 { margin: 1.55rem 0 0.65rem; color: rgb(var(--color-ink)); font-size: clamp(1.55rem, 2.4vw, 2.1rem); font-weight: 560; letter-spacing: -0.055em; line-height: 1; }
.journey-description { max-width: 34ch; margin: 0; color: rgb(var(--color-muted)); font-size: 0.94rem; line-height: 1.65; }
.journey-tags { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 1.1rem; }
.journey-tags .ds-tag { min-height: 1.65rem; padding: 0.32rem 0.58rem; font-size: 0.67rem; }

.education-section { padding-top: clamp(4rem, 7vw, 6.5rem); }
.education-heading-row { display: grid; grid-template-columns: minmax(150px, 0.55fr) minmax(0, 1.45fr); gap: clamp(2rem, 6vw, 6rem); align-items: start; margin-bottom: 2.5rem; }
.education-heading { font-size: clamp(2.8rem, 5.5vw, 5.5rem); }
.education-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.education-primary-wrap { grid-column: 1 / -1; }
.education-card { height: 100%; padding: clamp(1.25rem, 3vw, 2.25rem); }
.education-card-primary { min-height: 250px; }
.education-card-top { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.education-period { color: rgb(var(--color-muted)); font-size: 0.77rem; letter-spacing: 0.04em; white-space: nowrap; }
.education-primary-content { display: flex; align-items: flex-end; justify-content: space-between; gap: 2rem; margin-top: clamp(2rem, 4vw, 3.5rem); }
.education-card h3 { margin: 0; color: rgb(var(--color-ink)); font-size: clamp(1.8rem, 4vw, 3.5rem); font-weight: 560; letter-spacing: -0.06em; line-height: 1.04; }
.education-institution { max-width: 58ch; margin-top: 0.75rem; font-size: 0.95rem; line-height: 1.6; }
.education-result-primary { display: flex; flex: 0 0 auto; flex-direction: column; align-items: flex-end; gap: 0.15rem; border-left: 1px solid rgb(var(--color-line)); padding-left: 1.5rem; }
.education-result-primary span { color: rgb(var(--color-muted)); font-size: 0.67rem; letter-spacing: 0.11em; text-transform: uppercase; }
.education-result-primary strong { color: rgb(var(--color-accent)); font-size: clamp(2rem, 4vw, 3.2rem); font-weight: 540; letter-spacing: -0.07em; line-height: 1; }
.education-secondary-wrap { min-height: 178px; }
.education-card-secondary { display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto 1fr; align-items: start; background: rgb(var(--color-surface) / 0.72); box-shadow: none; }
.education-card-secondary .education-card-top { grid-column: 1 / -1; }
.education-secondary-title { align-self: end; margin-top: 2.1rem !important; font-size: clamp(1.8rem, 3vw, 2.55rem) !important; }
.education-secondary-result { align-self: end; margin: 0 0 0 1rem; color: rgb(var(--color-accent)); font-size: clamp(1.2rem, 2.2vw, 1.65rem); font-weight: 560; letter-spacing: -0.045em; white-space: nowrap; }

.project-showcase { padding-bottom: clamp(5rem, 9vw, 8rem); }
.projects-intro { display: flex; align-items: flex-end; justify-content: space-between; gap: 2rem; padding-top: clamp(4.5rem, 8vw, 7rem); padding-bottom: clamp(3rem, 5vw, 4.5rem); }
.projects-intro-copy { max-width: 820px; }
.projects-heading { margin-top: 1.1rem; font-size: clamp(3.25rem, 7.3vw, 6.6rem); }
.projects-introduction { max-width: 58ch; margin-top: 1.35rem; color: rgb(var(--color-muted)); font-size: clamp(1rem, 1.35vw, 1.13rem); }
.projects-intro-index { display: inline-flex; align-items: center; gap: 0.6rem; flex: 0 0 auto; margin-bottom: 0.3rem; color: rgb(var(--color-muted)); font-size: 0.67rem; letter-spacing: 0.09em; text-transform: uppercase; }
.projects-intro-index i { width: 23px; height: 1px; background: rgb(var(--color-line-strong)); }
.projects-list { width: 100%; }
.project-feature { display: grid; grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr); align-items: center; gap: clamp(2.5rem, 7vw, 7rem); border-top: 1px solid rgb(var(--color-line)); padding-top: clamp(3rem, 6vw, 5.5rem); padding-bottom: clamp(3.5rem, 7vw, 6rem); }
.project-feature-reverse { grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr); }
.project-feature-reverse .project-copy { grid-column: 2; grid-row: 1; }
.project-feature-reverse .project-preview { grid-column: 1; grid-row: 1; }
.project-copy { min-width: 0; }
.project-meta { display: flex; align-items: center; gap: 0.62rem; margin: 0; color: rgb(var(--color-muted)); font-size: 0.69rem; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; }
.project-meta > span { color: rgb(var(--color-accent)); }
.project-meta i { width: 20px; height: 1px; background: rgb(var(--color-line-strong)); }
.project-title { max-width: 16ch; margin: 1.35rem 0 0; color: rgb(var(--color-ink)); font-size: clamp(2.25rem, 4.1vw, 4.15rem); font-weight: 540; letter-spacing: -0.07em; line-height: 1.01; text-wrap: balance; }
.project-subtitle { margin: 0.55rem 0 0; color: rgb(var(--color-ink) / 0.78); font-size: clamp(0.94rem, 1.4vw, 1.1rem); font-weight: 540; letter-spacing: -0.025em; }
.project-description { max-width: 53ch; margin: 1.2rem 0 0; color: rgb(var(--color-muted)); font-size: 0.98rem; line-height: 1.75; }
.project-technologies { display: flex; flex-wrap: wrap; gap: 0.45rem; margin: 1.4rem 0 0; padding: 0; list-style: none; }
.project-technologies .ds-tag { min-height: 1.7rem; padding: 0.3rem 0.6rem; font-size: 0.68rem; }
.project-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 1.35rem; margin-top: 1.65rem; }
.project-case-link, .project-github-link, .repositories-link { display: inline-flex; align-items: center; gap: 0.42rem; color: rgb(var(--color-accent)); font-size: 0.83rem; font-weight: 580; text-decoration: none; transition: color 160ms ease; }
.project-github-link { color: rgb(var(--color-muted)); }
.project-case-link svg, .repositories-link svg { transition: transform 180ms ease; }
.project-case-link:hover, .project-github-link:hover, .repositories-link:hover { color: rgb(var(--color-accent-hover)); }
.project-case-link:hover svg, .repositories-link:hover svg { transform: translate(2px, -2px); }
.project-preview { min-width: 0; border-radius: clamp(1.15rem, 2vw, 1.7rem); background: rgb(var(--color-surface) / 0.78); box-shadow: var(--shadow-soft); transition: border-color 220ms ease, box-shadow 220ms ease; }
.project-feature:hover .project-preview { border-color: rgb(var(--color-accent) / 0.2); box-shadow: var(--shadow-float); }
