.technical-focus-card-heading { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.technical-focus-number { color: rgb(var(--color-accent)); font-size: .72rem; font-weight: 620; letter-spacing: .08em; }
.technical-focus-label { color: rgb(var(--color-muted)); font-size: .64rem; letter-spacing: .09em; text-transform: uppercase; }
.technical-focus-card h3 { max-width: 22ch; margin: 1.35rem 0 0; color: rgb(var(--color-ink)); font-size: clamp(1.6rem, 3vw, 2.35rem); font-weight: 550; letter-spacing: -.055em; line-height: 1.05; text-wrap: balance; }
.technical-focus-description { max-width: 53ch; margin: .75rem 0 0; color: rgb(var(--color-muted)); font-size: .9rem; line-height: 1.7; }
.focus-flow { display: flex; flex-wrap: wrap; align-items: center; gap: .35rem; margin: 1.25rem 0 0; padding: .7rem 0; list-style: none; }
.focus-flow li { display: inline-flex; min-width: 0; align-items: center; gap: .35rem; color: rgb(var(--color-accent)); font-size: .67rem; font-weight: 560; }
.focus-flow li span { border: 1px solid rgb(var(--color-line)); border-radius: 999px; padding: .35rem .55rem; background: rgb(var(--color-surface) / .72); color: rgb(var(--color-ink) / .83); white-space: normal; }
.focus-flow li svg { flex: 0 0 auto; color: rgb(var(--color-muted)); }
.focus-tech-list, .credential-skills { display: flex; flex-wrap: wrap; gap: .4rem; margin: 1rem 0 0; padding: 0; list-style: none; }
.focus-tech-list .ds-tag, .credential-skills .ds-tag { min-height: 1.65rem; padding: .3rem .58rem; font-size: .66rem; transition: transform 160ms ease, border-color 160ms ease, color 160ms ease; }
.focus-tech-list li:hover .ds-tag, .credential-skills li:hover .ds-tag { transform: translateY(-2px); border-color: rgb(var(--color-accent) / .3); color: rgb(var(--color-accent)); }
.focus-proof-layout { display: grid; grid-template-columns: minmax(0, 1fr); align-items: center; gap: 2rem; margin-top: 1.35rem; }
.focus-proof-copy { min-width: 0; }
.focus-proof-link { display: flex; align-items: center; justify-content: space-between; gap: 1rem; border: 1px solid rgb(var(--color-line)); border-radius: .95rem; padding: .85rem 1rem; background: rgb(var(--color-surface) / .72); color: rgb(var(--color-ink)); text-decoration: none; transition: border-color 160ms ease, background-color 160ms ease; }
.focus-proof-link:is(:hover, :focus-visible) { border-color: rgb(var(--color-accent) / .35); background: rgb(var(--color-surface)); }
.focus-proof-link > span { display: grid; gap: .18rem; }
.focus-proof-link strong { font-size: 1.02rem; font-weight: 580; letter-spacing: -.03em; }
.focus-proof-link small { color: rgb(var(--color-muted)); font-size: .73rem; }
.focus-proof-link > svg { flex: 0 0 auto; color: rgb(var(--color-accent)); transition: transform 160ms ease; }
.focus-proof-link:is(:hover, :focus-visible) > svg { transform: translate(2px, -2px); }
.focus-flow-security { display: grid; justify-items: center; gap: .2rem; margin: 0; padding: 0; }
.focus-flow-security li { display: flex; flex-direction: column; align-items: center; gap: .05rem; font-size: .66rem; }
.focus-flow-security li span { min-width: 160px; border-color: rgb(var(--color-accent) / .18); padding: .38rem .7rem; text-align: center; }
.focus-flow-security li svg { color: rgb(var(--color-accent) / .7); }
.credentials-section { border-top: 1px solid rgb(var(--color-line)); padding-top: clamp(4rem, 7vw, 6rem); }
.credentials-heading { font-size: clamp(2.8rem, 5.5vw, 5.5rem); }
.credentials-heading-copy > p { margin: .8rem 0 0; color: rgb(var(--color-muted)); font-size: .95rem; }
.credentials-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: .8rem; }
.credential-card { display: flex; height: 100%; min-height: 250px; flex-direction: column; align-items: flex-start; padding: clamp(1.2rem, 2.3vw, 1.7rem); transition: border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease; }
.credentials-grid article:hover .credential-card { transform: translateY(-2px); border-color: rgb(var(--color-accent) / .27); box-shadow: var(--shadow-soft); }
.credential-card-top { display: flex; width: 100%; align-items: center; justify-content: space-between; gap: .8rem; }
.credential-index { color: rgb(var(--color-accent)); font-size: .7rem; font-weight: 620; letter-spacing: .08em; }
.credential-score { display: inline-flex; align-items: center; gap: .4rem; color: rgb(var(--color-muted)); font-size: .67rem; }
.credential-score strong { color: rgb(var(--color-accent)); font-size: .86rem; font-weight: 580; }
.credential-card h3 { margin: 1.7rem 0 0; color: rgb(var(--color-ink)); font-size: clamp(1.15rem, 1.8vw, 1.5rem); font-weight: 560; letter-spacing: -.04em; line-height: 1.18; text-wrap: balance; }
.credential-issuer { margin: .55rem 0 0; color: rgb(var(--color-muted)); font-size: .8rem; line-height: 1.55; }
.credential-description { margin: .8rem 0 0; color: rgb(var(--color-ink) / .78); font-size: .82rem; line-height: 1.6; }
.credential-skills { margin-top: auto; padding-top: 1rem; }

@media (max-width: 960px) {
  .technical-focus-intro, .credentials-heading-row { grid-template-columns: minmax(120px, .42fr) minmax(0, 1.58fr); gap: 2.25rem; }
  .credentials-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .credential-card { min-height: 230px; }
}
@media (max-width: 700px) {
  .technical-focus-section { padding-top: 4.2rem; }
  .technical-focus-intro, .credentials-heading-row { grid-template-columns: 1fr; gap: 1.35rem; margin-bottom: 1.6rem; }
  .technical-focus-heading { font-size: clamp(2.9rem, 10.5vw, 4.1rem); }
  .technical-focus-lede { margin-top: .8rem; font-size: .97rem; }
  .technical-focus-grid { grid-template-columns: 1fr; gap: .7rem; }
  .technical-focus-card-wrap-emphasis { grid-column: auto; grid-row: auto; }
  .technical-focus-card { padding: 1.2rem; }
  .technical-focus-card h3 { font-size: 1.8rem; }
  .technical-focus-description { font-size: .87rem; }
  .focus-proof-layout { grid-template-columns: minmax(0, 1fr) minmax(118px, .7fr); gap: .7rem; }
  .focus-flow-security li span { min-width: 0; width: 100%; padding-inline: .4rem; font-size: .61rem; }
  .focus-flow-security li { width: 100%; }
  .focus-tech-list { gap: .35rem; }
  .focus-tech-list .ds-tag { font-size: .62rem; }
  .credentials-section { padding-top: 3.5rem; }
  .credentials-heading { font-size: clamp(2.8rem, 10vw, 4rem); }
  .credentials-grid { grid-template-columns: 1fr; gap: .7rem; }
  .credential-card { min-height: 0; padding: 1.2rem; }
  .credential-card h3 { margin-top: 1.3rem; font-size: 1.35rem; }
  .credential-skills { margin-top: .9rem; padding-top: 0; }
}
@media (max-width: 480px) {
  .focus-proof-layout { grid-template-columns: 1fr; }
  .focus-flow-security { grid-template-columns: 1fr; }
  .focus-flow-security li { max-width: 220px; }
  .focus-flow-security li span { min-height: 2.2rem; display: grid; place-items: center; }
}
@media (prefers-reduced-motion: reduce) {
  .technical-focus-module *, .technical-focus-module *::before, .technical-focus-module *::after { scroll-behavior: auto; transition-duration: .01ms !important; }
  .technical-focus-module .technical-focus-card, .technical-focus-module .credential-card, .technical-focus-module .ds-tag, .technical-focus-module .focus-proof-link > svg { transform: none !important; }
}

showcase:
"use client";

import { motion, useReducedMotion, type Variants } from "framer-motion";
import { ArrowDown, ArrowRight, ArrowUpRight, Github } from "lucide-react";
import { BodyText, Card, SectionHeading, Tag } from "@/components/ui";
import { portfolio, type Project } from "@/data/portfolio";

const reveal: Variants = {
  hidden: { opacity: 0, y: 22 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.62, ease: [0.22, 1, 0.36, 1] } },
};

function ProjectVisual({ project }: { project: Project }) {
  const isHospital = project.visualType === "hospital-flow";
  const isEmergency = project.visualType === "emergency-flow";
  const isLead = project.visualType === "lead-flow";

  return (
    <div className={`project-visual project-visual-${project.visualType}`} role="img" aria-label={`${project.title} conceptual system diagram: ${project.visualNodes.join(", then ")}`}>
      <div className="project-visual-top" aria-hidden="true">
        <span className="project-visual-kicker">System map</span>
        <span className="project-visual-index">{project.number} / 04</span>
      </div>
      <div className={`project-flow ${isHospital ? "project-flow-hospital" : ""}`} aria-hidden="true">
        {project.visualNodes.map((node, index) => {
          const grouped = isHospital && index < 3;
          const connector = index < project.visualNodes.length - 1;
          const shouldDown = !isHospital;
          return (
            <div className={`project-flow-step ${grouped ? "project-flow-source" : ""} ${isEmergency && index === 3 ? "project-flow-branch" : ""}`} key={node}>
              <span className={`project-flow-node ${index === project.visualNodes.length - 1 ? "project-flow-node-final" : ""}`}>
                {!grouped && <span className="project-flow-dot" />}
                {node}
              </span>
              {connector && (isEmergency && index === 2 ? <span className="project-flow-plus">+</span> : shouldDown ? <ArrowDown className="project-flow-arrow" size={15} /> : <ArrowRight className="project-flow-arrow" size={15} />)}
            </div>
          );
        })}
      </div>
      <span className="project-visual-note" aria-hidden="true">Conceptual flow</span>
    </div>
  );
}

function ProjectLinks({ project }: { project: Project }) {
  return (
    <div className="project-actions">
      <a className="project-case-link" href={project.caseStudy} aria-label={`View ${project.title} case study`}>
        View Case Study <ArrowRight size={16} strokeWidth={1.8} aria-hidden="true" />
      </a>
      {project.github && (
        <a className="project-github-link" href={project.github} target="_blank" rel="noreferrer" aria-label={`${project.title} on GitHub`}>
          <Github size={16} strokeWidth={1.8} aria-hidden="true" /> GitHub <ArrowUpRight size={14} strokeWidth={1.8} aria-hidden="true" />
        </a>
      )}
    </div>
  );
}

export function ProjectShowcase() {
  const reduceMotion = useReducedMotion();
  const initial = reduceMotion ? false : "hidden";
  const { projectShowcase, projects } = portfolio;

  return (
    <section className="project-showcase" id="work" aria-labelledby="projects-heading">
      <div className="editorial-section projects-intro">
        <motion.div className="projects-intro-copy" variants={reveal} initial={initial} whileInView="visible" viewport={{ once: true, amount: 0.4 }}>
          <p className="ds-eyebrow">{projectShowcase.eyebrow}</p>
          <SectionHeading id="projects-heading" className="projects-heading">{projectShowcase.heading}</SectionHeading>
          <BodyText className="projects-introduction">{projectShowcase.introduction}</BodyText>
        </motion.div>
        <span className="projects-intro-index" aria-hidden="true">04 <i /> Work</span>
      </div>

      <div className="projects-list">
        {projects.map((project, index) => {
          const reverse = index % 2 === 1;
          return (
            <motion.article
              className={`editorial-section project-feature ${reverse ? "project-feature-reverse" : ""}`}
              key={project.id}
              variants={reveal}
              initial={initial}
              whileInView="visible"
              viewport={{ once: true, amount: 0.18 }}
              aria-labelledby={`project-${project.id}-title`}
            >
              <div className="project-copy">
                <p className="project-meta"><span>{project.number}</span><i />{project.category}</p>
                <h3 className="project-title" id={`project-${project.id}-title`}>{project.title}</h3>
                {project.subtitle && <p className="project-subtitle">{project.subtitle}</p>}
                <p className="project-description">{project.description}</p>
                <ul className="project-technologies" aria-label={`${project.title} technologies`}>
                  {project.technologies.map((technology) => <li key={technology}><Tag>{technology}</Tag></li>)}
                </ul>
                <ProjectLinks project={project} />
              </div>
              <Card className="project-preview"><ProjectVisual project={project} /></Card>
            </motion.article>
          );
        })}
      </div>

      <div className="editorial-section more-projects" aria-labelledby="more-projects-heading">
        <div className="more-projects-heading-row">
          <div>
            <p className="ds-eyebrow">Beyond the featured work</p>
            <SectionHeading id="more-projects-heading" className="more-projects-heading">{projectShowcase.moreHeading}</SectionHeading>
          </div>
          <a className="repositories-link" href="https://github.com/NIKHILKAKADEK" target="_blank" rel="noreferrer">
            Explore all repositories <ArrowUpRight size={15} aria-hidden="true" />
          </a>
        </div>
        <ul className="repository-list">
          {projectShowcase.repositories.map((repository, index) => (
            <li key={repository.name}>
              <a className="repository-row" href={repository.github} target="_blank" rel="noreferrer" aria-label={`${repository.name} repository on GitHub`}>
                <span className="repository-index">0{index + 1}</span>
                <span className="repository-name">{repository.name}</span>
                {repository.language && <span className="repository-language">{repository.language}</span>}
                <ArrowUpRight className="repository-arrow" size={17} aria-hidden="true" />
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
